PAYLOAD=''
SOURCE_SHA='53e94ea536a981bf850b673e8448e3600e0790c63459f59da333e2b0773bb8e6'
import base64,gzip,hashlib,json,subprocess,sys
from pathlib import Path
raw=gzip.decompress(base64.b64decode(PAYLOAD));assert hashlib.sha256(raw).hexdigest()==SOURCE_SHA
assert hashlib.sha256(Path('/etc/systemd/system/aura-camera-ui.service').read_bytes()).hexdigest()=='29786434df9bb9b94a8e640a7a48db47019c224d3876037ce27d3467bb2f5512'
root=Path('/home/root/aura-gui-cpu-20261023')/SOURCE_SHA[:16];root.mkdir(parents=True,exist_ok=True,mode=0o700)
source=Path(sys._getframe().f_code.co_filename).resolve()
args=sys.argv[1:];assert args in ([],['--run'],['--child'])
if args==['--run']:exec(compile(raw,'fixed-visual-profile','exec'))
elif args==['--child']:
 r=subprocess.run(['/usr/bin/python3','-B',str(source),'--run'],capture_output=True,text=True,timeout=85)
 (root/'stdout.json').write_text(r.stdout);(root/'stderr.log').write_text(r.stderr)
 (root/'done.json').write_text(json.dumps({'exit_code':r.returncode}))
else:
 assert not (root/'done.json').exists(),'Do not overwrite a profile'
 unit='aura-gui-profile-'+SOURCE_SHA[:16]
 r=subprocess.run(['systemd-run','--unit='+unit,'--property=RuntimeMaxSec=100','--property=Nice=10',
  '/usr/bin/python3','-B',str(source),'--child'],capture_output=True,text=True,timeout=8)
 assert r.returncode==0,r.stderr
 print(json.dumps({'started':True,'root':str(root),'unit':unit,'source_sha256':SOURCE_SHA}))
